const input = $json || {};
const workspace_id = input.workspace_id || $env.VF_WORKSPACE_ID;
const experiment_id = input.experiment_id;
const video_job_id = input.video_job_id;

if (!workspace_id) throw new Error('VF_CANARY: workspace_id missing');
if (!experiment_id) throw new Error('VF_CANARY: experiment_id missing');
if (!video_job_id) throw new Error('VF_CANARY: video_job_id missing');

return [{
  json: {
    workspace_id,
    experiment_id,
    video_job_id
  }
}];

const response = $json || {};
if (response.ok !== true || !response.data) {
  throw new Error('VF_CANARY: assignment API returned invalid response');
}

const data = response.data;
return [{
  json: {
    vf_canary: {
      enabled: Boolean(data.eligible),
      eligible: Boolean(data.eligible),
      reason: data.reason || null,
      workspace_id: data.workspace_id || null,
      experiment_id: data.experiment_id || null,
      variant_key: data.assignment?.variant_key || null,
      bucket: data.assignment?.bucket ?? null,
      assignment_version: data.assignment?.assignment_version || null,
      profile_key: data.profile_key || null,
      automatic_promotion: false
    }
  }
}];
